def apply_discount(price: float, percent: float) -> float:
    """Return price reduced by `percent` percent, rounded to 2 decimals.

    Per the README spec: ``apply_discount(100.0, 15)`` -> ``85.0``.
    """
    discounted = price - (price * percent / 100.0)
    return float(round(discounted, 2))
